import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64
.visible .entry conv2d_kernel(
    .param .u64 X_ptr,
    .param .u64 W_ptr,
    .param .u64 B_ptr,
    .param .u64 Y_ptr,
    .param .u32 N,
    .param .u32 Cin,
    .param .u32 H,
    .param .u32 Win,
    .param .u32 Cout,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 padding,
    .param .u32 dilation,
    .param .u32 groups,
    .param .u32 Hout,
    .param .u32 Wout,
    .param .u32 CinPerGroup,
    .param .u32 CoutPerGroup,
    .param .u32 total,
    .param .u32 has_bias
)
{
    // Register-pressure reduction optimization: the previous CTA design used
    // 16x16=256 threads each computing a 2x2 spatial sub-tile x 8 output
    // channels (32 FMA accumulators/thread), which drove register usage to
    // ~121 regs/thread and capped theoretical occupancy at ~33% (profiler-
    // confirmed, register-limited). This version keeps the same 32x32 CTA
    // output tile and 8-output-channel shared-memory reuse (identical
    // activation-tile staging + weight staging + DRAM traffic), but maps the
    // work over a full 32x32=1024-thread CTA with ONE output spatial
    // position per thread (8 accumulators/thread instead of 32). This is a
    // register-blocking reduction: fewer live accumulators and simpler
    // per-tap address arithmetic sharply cut registers/thread, allowing many
    // more resident warps per SM and better latency hiding, while preserving
    // identical numerics and DRAM-traffic reuse characteristics.
    .shared .align 4 .b8 shTile[4624];   // 34 x 34 floats (32+2 wide, 32+2 tall)
    .shared .align 4 .b8 shWeight[288];  // 8 x 3x3 weight tap cache (72 floats)
    .reg .pred %p<300>;
    .reg .b32 %r<1500>;
    .reg .b64 %rd<950>;
    .reg .f32 %f<300>;
    ld.param.u64 %rd1, [X_ptr];
    ld.param.u64 %rd2, [W_ptr];
    ld.param.u64 %rd3, [B_ptr];
    ld.param.u64 %rd4, [Y_ptr];
    ld.param.u32 %r1,  [N];
    ld.param.u32 %r2,  [Cin];
    ld.param.u32 %r3,  [H];
    ld.param.u32 %r4,  [Win];
    ld.param.u32 %r5,  [Cout];
    ld.param.u32 %r6,  [K];
    ld.param.u32 %r7,  [stride];
    ld.param.u32 %r8,  [padding];
    ld.param.u32 %r9,  [dilation];
    ld.param.u32 %r10, [groups];
    ld.param.u32 %r11, [Hout];
    ld.param.u32 %r12, [Wout];
    ld.param.u32 %r13, [CinPerGroup];
    ld.param.u32 %r14, [CoutPerGroup];
    ld.param.u32 %r15, [total];
    ld.param.u32 %r16, [has_bias];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd4, %rd4;
    mov.u32 %r20, %tid.x;
    mov.u32 %r21, %tid.y;
    mov.u32 %r22, %ctaid.x;
    mov.u32 %r23, %ctaid.y;
    mov.u32 %r24, %ctaid.z;
    mul.lo.s32 %r25, %r22, 32;
    mul.lo.s32 %r26, %r23, 32;
    add.s32 %r27, %r25, %r20;
    add.s32 %r28, %r26, %r21;
    add.s32 %r104, %r5, 7;
    div.s32 %r105, %r104, 8;      // OcOctets = ceil(Cout/8)
    div.s32 %r106, %r24, %r105;   // n
    rem.s32 %r107, %r24, %r105;   // octetIdx
    mul.lo.s32 %r108, %r107, 8;   // oc0
    add.s32 %r109, %r108, 1;      // oc1
    add.s32 %r110, %r108, 2;      // oc2
    add.s32 %r111, %r108, 3;      // oc3
    add.s32 %r112, %r108, 4;      // oc4
    add.s32 %r113, %r108, 5;      // oc5
    add.s32 %r114, %r108, 6;      // oc6
    add.s32 %r115, %r108, 7;      // oc7
    div.s32 %r116, %r108, %r14;   // g0
    div.s32 %r117, %r109, %r14;   // g1
    div.s32 %r118, %r110, %r14;   // g2
    div.s32 %r119, %r111, %r14;   // g3
    div.s32 %r120, %r112, %r14;   // g4
    div.s32 %r121, %r113, %r14;   // g5
    div.s32 %r122, %r114, %r14;   // g6
    div.s32 %r123, %r115, %r14;   // g7
    setp.lt.s32 %p57, %r109, %r5;
    setp.eq.s32 %p58, %r117, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p50, %p59;          // invalid1
    selp.b32 %r124, %r109, %r108, %p59;  // oc1_safe
    setp.lt.s32 %p57, %r110, %r5;
    setp.eq.s32 %p58, %r118, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p51, %p59;          // invalid2
    selp.b32 %r125, %r110, %r108, %p59;  // oc2_safe
    setp.lt.s32 %p57, %r111, %r5;
    setp.eq.s32 %p58, %r119, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p52, %p59;          // invalid3
    selp.b32 %r126, %r111, %r108, %p59;  // oc3_safe
    setp.lt.s32 %p57, %r112, %r5;
    setp.eq.s32 %p58, %r120, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p53, %p59;          // invalid4
    selp.b32 %r127, %r112, %r108, %p59;  // oc4_safe
    setp.lt.s32 %p57, %r113, %r5;
    setp.eq.s32 %p58, %r121, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p54, %p59;          // invalid5
    selp.b32 %r128, %r113, %r108, %p59;  // oc5_safe
    setp.lt.s32 %p57, %r114, %r5;
    setp.eq.s32 %p58, %r122, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p55, %p59;          // invalid6
    selp.b32 %r129, %r114, %r108, %p59;  // oc6_safe
    setp.lt.s32 %p57, %r115, %r5;
    setp.eq.s32 %p58, %r123, %r116;
    and.pred %p59, %p57, %p58;
    not.pred %p56, %p59;          // invalid7
    selp.b32 %r130, %r115, %r108, %p59;  // oc7_safe
    mul.lo.s32 %r131, %r116, %r13;   // ic_base (group of oc0)
    mad.lo.s32 %r33, %r21, 32, %r20;   // flatTid (0..1023)
    mov.f32 %f60, 0f00000000;
    mov.f32 %f61, 0f00000000;
    mov.f32 %f62, 0f00000000;
    mov.f32 %f63, 0f00000000;
    mov.f32 %f64, 0f00000000;
    mov.f32 %f65, 0f00000000;
    mov.f32 %f66, 0f00000000;
    mov.f32 %f67, 0f00000000;
    setp.eq.s32 %p1, %r16, 0;
    @%p1 bra SKIP_BIAS;
    cvta.to.global.u64 %rd60, %rd3;
    mul.wide.s32 %rd61, %r108, 4;
    add.s64 %rd62, %rd60, %rd61;
    ld.global.f32 %f60, [%rd62];
    mul.wide.s32 %rd63, %r124, 4;
    add.s64 %rd64, %rd60, %rd63;
    ld.global.f32 %f61, [%rd64];
    mul.wide.s32 %rd65, %r125, 4;
    add.s64 %rd66, %rd60, %rd65;
    ld.global.f32 %f62, [%rd66];
    mul.wide.s32 %rd67, %r126, 4;
    add.s64 %rd68, %rd60, %rd67;
    ld.global.f32 %f63, [%rd68];
    mul.wide.s32 %rd69, %r127, 4;
    add.s64 %rd70, %rd60, %rd69;
    ld.global.f32 %f64, [%rd70];
    mul.wide.s32 %rd71, %r128, 4;
    add.s64 %rd72, %rd60, %rd71;
    ld.global.f32 %f65, [%rd72];
    mul.wide.s32 %rd73, %r129, 4;
    add.s64 %rd74, %rd60, %rd73;
    ld.global.f32 %f66, [%rd74];
    mul.wide.s32 %rd75, %r130, 4;
    add.s64 %rd76, %rd60, %rd75;
    ld.global.f32 %f67, [%rd76];
SKIP_BIAS:
    mov.u32 %r34, shTile;
    mov.u32 %r40, 0;
LOOP_IC:
    setp.ge.s32 %p2, %r40, %r13;
    @%p2 bra END_IC;
    mad.lo.s32 %r700, %r108, %r13, %r40;
    mul.lo.s32 %r701, %r6, %r6;
    mul.lo.s32 %r702, %r700, %r701;   // wbase0
    mad.lo.s32 %r703, %r124, %r13, %r40;
    mul.lo.s32 %r704, %r703, %r701;   // wbase1
    mad.lo.s32 %r705, %r125, %r13, %r40;
    mul.lo.s32 %r706, %r705, %r701;   // wbase2
    mad.lo.s32 %r707, %r126, %r13, %r40;
    mul.lo.s32 %r708, %r707, %r701;   // wbase3
    mad.lo.s32 %r709, %r127, %r13, %r40;
    mul.lo.s32 %r710, %r709, %r701;   // wbase4
    mad.lo.s32 %r711, %r128, %r13, %r40;
    mul.lo.s32 %r712, %r711, %r701;   // wbase5
    mad.lo.s32 %r713, %r129, %r13, %r40;
    mul.lo.s32 %r714, %r713, %r701;   // wbase6
    mad.lo.s32 %r715, %r130, %r13, %r40;
    mul.lo.s32 %r716, %r715, %r701;   // wbase7
    add.s32 %r720, %r131, %r40;       // ic_base+ic
    // ---- cooperative load pass 0: idx = flatTid (0..1023) ----
    div.s32 %r141, %r33, 34;
    rem.s32 %r142, %r33, 34;
    sub.s32 %r143, %r26, %r8;
    add.s32 %r143, %r143, %r141;
    sub.s32 %r144, %r25, %r8;
    add.s32 %r144, %r144, %r142;
    setp.lt.s32 %p3, %r143, 0;
    setp.ge.s32 %p4, %r143, %r3;
    or.pred %p5, %p3, %p4;
    setp.lt.s32 %p6, %r144, 0;
    setp.ge.s32 %p7, %r144, %r4;
    or.pred %p8, %p6, %p7;
    or.pred %p9, %p5, %p8;
    mov.f32 %f2, 0f00000000;
    @%p9 bra STORE_A0;
    mad.lo.s32 %r146, %r106, %r2, %r720;
    mad.lo.s32 %r147, %r146, %r3, %r143;
    mad.lo.s32 %r148, %r147, %r4, %r144;
    mul.wide.s32 %rd20, %r148, 4;
    add.s64 %rd21, %rd1, %rd20;
    ld.global.f32 %f2, [%rd21];
STORE_A0:
    mul.lo.s32 %r149, %r33, 4;
    add.s32 %r150, %r34, %r149;
    st.shared.f32 [%r150], %f2;
    // ---- cooperative load pass 1 (tail): idx = flatTid+1024, valid < 1156 ----
    add.s32 %r160, %r33, 1024;
    setp.ge.s32 %p10, %r160, 1156;
    @%p10 bra AFTER_LOAD_A1;
    div.s32 %r161, %r160, 34;
    rem.s32 %r162, %r160, 34;
    sub.s32 %r163, %r26, %r8;
    add.s32 %r163, %r163, %r161;
    sub.s32 %r164, %r25, %r8;
    add.s32 %r164, %r164, %r162;
    setp.lt.s32 %p3, %r163, 0;
    setp.ge.s32 %p4, %r163, %r3;
    or.pred %p5, %p3, %p4;
    setp.lt.s32 %p6, %r164, 0;
    setp.ge.s32 %p7, %r164, %r4;
    or.pred %p8, %p6, %p7;
    or.pred %p9, %p5, %p8;
    mov.f32 %f2, 0f00000000;
    @%p9 bra STORE_A1;
    mad.lo.s32 %r166, %r106, %r2, %r720;
    mad.lo.s32 %r167, %r166, %r3, %r163;
    mad.lo.s32 %r168, %r167, %r4, %r164;
    mul.wide.s32 %rd22, %r168, 4;
    add.s64 %rd23, %rd1, %rd22;
    ld.global.f32 %f2, [%rd23];
STORE_A1:
    mul.lo.s32 %r169, %r160, 4;
    add.s32 %r170, %r34, %r169;
    st.shared.f32 [%r170], %f2;
AFTER_LOAD_A1:
    // ---- cooperative staging of the 3x3 weight taps for oc0..oc7 into shared memory ----
    setp.ge.s32 %p26, %r33, 9;
    @%p26 bra SKIP_WLOAD;
    mul.lo.s32 %r750, %r33, 4;
    mov.u32 %r751, shWeight;
    add.s32 %r752, %r751, %r750;
    add.s32 %r753, %r702, %r33;
    mul.wide.s32 %rd150, %r753, 4;
    add.s64 %rd151, %rd2, %rd150;
    ld.global.f32 %f200, [%rd151];
    st.shared.f32 [%r752], %f200;
    add.s32 %r754, %r704, %r33;
    mul.wide.s32 %rd152, %r754, 4;
    add.s64 %rd153, %rd2, %rd152;
    ld.global.f32 %f201, [%rd153];
    add.s32 %r755, %r752, 36;
    st.shared.f32 [%r755], %f201;
    add.s32 %r756, %r706, %r33;
    mul.wide.s32 %rd154, %r756, 4;
    add.s64 %rd155, %rd2, %rd154;
    ld.global.f32 %f202, [%rd155];
    add.s32 %r757, %r752, 72;
    st.shared.f32 [%r757], %f202;
    add.s32 %r758, %r708, %r33;
    mul.wide.s32 %rd156, %r758, 4;
    add.s64 %rd157, %rd2, %rd156;
    ld.global.f32 %f203, [%rd157];
    add.s32 %r759, %r752, 108;
    st.shared.f32 [%r759], %f203;
    add.s32 %r760, %r710, %r33;
    mul.wide.s32 %rd158, %r760, 4;
    add.s64 %rd159, %rd2, %rd158;
    ld.global.f32 %f204, [%rd159];
    add.s32 %r761, %r752, 144;
    st.shared.f32 [%r761], %f204;
    add.s32 %r762, %r712, %r33;
    mul.wide.s32 %rd160, %r762, 4;
    add.s64 %rd161, %rd2, %rd160;
    ld.global.f32 %f205, [%rd161];
    add.s32 %r763, %r752, 180;
    st.shared.f32 [%r763], %f205;
    add.s32 %r764, %r714, %r33;
    mul.wide.s32 %rd162, %r764, 4;
    add.s64 %rd163, %rd2, %rd162;
    ld.global.f32 %f206, [%rd163];
    add.s32 %r765, %r752, 216;
    st.shared.f32 [%r765], %f206;
    add.s32 %r766, %r716, %r33;
    mul.wide.s32 %rd164, %r766, 4;
    add.s64 %rd165, %rd2, %rd164;
    ld.global.f32 %f207, [%rd165];
    add.s32 %r767, %r752, 252;
    st.shared.f32 [%r767], %f207;
SKIP_WLOAD:
    bar.sync 0;
    mov.u32 %r800, shWeight;
    add.s32 %r801, %r800, 36;
    add.s32 %r802, %r800, 72;
    add.s32 %r803, %r800, 108;
    add.s32 %r804, %r800, 144;
    add.s32 %r805, %r800, 180;
    add.s32 %r806, %r800, 216;
    add.s32 %r807, %r800, 252;
    mul.lo.s32 %r300, %r21, 34;
    add.s32 %r301, %r300, 34;
    add.s32 %r302, %r301, 34;
    mov.u32 %r310, %r20;
    add.s32 %r311, %r20, 1;
