    fma.rn.f32 %f60, %f10, %f100, %f60;
    ld.shared.f32 %f100, [%r801+0];
    fma.rn.f32 %f61, %f10, %f100, %f61;
    ld.shared.f32 %f100, [%r802+0];
    fma.rn.f32 %f62, %f10, %f100, %f62;
    ld.shared.f32 %f100, [%r803+0];
    fma.rn.f32 %f63, %f10, %f100, %f63;
